 "content": "from collections import deque


def transform(grid):
    """Reverse the color order of each separate nested rectangular object."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0
                            and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            boxes = {}
            for y, x in cells:
                color = grid[y][x]
                if color not in boxes:
                    boxes[color] = [y, y, x, x]
                else:
                    b = boxes[color]
                    b[0] = min(b[0], y)
                    b[1] = max(b[1], y)
                    b[2] = min(b[2], x)
                    b[3] = max(b[3], x)
            ordered = sorted(boxes, key=lambda color: (
                (boxes[color][1] - boxes[color][0] + 1) *
                (boxes[color][3] - boxes[color][2] + 1)
            ), reverse=True)
            remap = {old: new for old, new in zip(ordered, reversed(ordered))}
            for y, x in cells:
                out[y][x] = remap[grid[y][x]]
    return out
